mkdirSync(path.dirname(path.resolve(dbPath)), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
)`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0
)`);
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) SELECT ?, ? WHERE EXISTS (SELECT 1 FROM projects WHERE id = ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

const mime = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (taskRoute && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify(listTasks.all(Number(taskRoute[1]))));
    return;
  }
  if (taskRoute && req.method === 'POST') {
    try {
      let body = ''; for await (const chunk of req) body += chunk;
      const title = String(JSON.parse(body).title ?? '').trim();
      if (!title) { res.writeHead(400, { 'content-type': 'application/json' }); res.end(JSON.stringify({ error: 'Task title is required' })); return; }
      const projectId = Number(taskRoute[1]);
      const result = createTask.run(projectId, title, projectId);
      if (!Number(result.changes)) { res.writeHead(404); res.end(); return; }
      res.writeHead(201, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ id: Number(result.lastInsertRowid), projectId, title, completed: 0 }));
    } catch { res.writeHead(400); res.end(); }
    return;
  }
  const completionRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (completionRoute && req.method === 'PATCH') {
    try {
      let body = ''; for await (const chunk of req) body += chunk;
      const completed = JSON.parse(body).completed ? 1 : 0;
      const result = updateTask.run(completed, Number(completionRoute[2]), Number(completionRoute[1]));
      res.writeHead(result.changes ? 204 : 404); res.end();
    } catch { res.writeHead(400); res.end(); }
    return;
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify(listProjects.all()));
    return;
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    try {
      const name = String(JSON.parse(body).name ?? '').trim();
      if (!name) {
        res.writeHead(400, { 'content-type': 'application/json' });
        res.end(JSON.stringify({ error: 'Project name is required' }));
        return;
      }
      const result = createProject.run(name);
      res.writeHead(201, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ id: Number(result.lastInsertRowid), name }));
    } catch {
      res.writeHead(400, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    try {
      const html = await readFile(path.join(root, 'index.html'));
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(html);
    } catch {
      res.writeHead(500); res.end('Unable to load application');
    }
    return;
  }
  if (req.method === 'GET' && ['/app.js', '/style.css'].includes(url.pathname)) {
    const file = path.join(root, url.pathname.slice(1));
    try {
      res.writeHead(200, { 'content-type': mime[path.extname(file)] });
      res.end(await readFile(file));
    } catch { res.writeHead(404); res.end('Not found'); }
    return;
  }
  res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  res.end('Not found');
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));

const app = document.querySelector('#app');

function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

async function projects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Unable to load projects');
  return response.json();
}

function navigate(path) {
  history.pushState({}, '', path);
  render();
}

async function render() {
  app.replaceChildren();
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    let items;
    try { items = await projects(); } catch { app.append(element('p', 'Unable to load projects')); return; }
    const project = items.find(item => String(item.id) === match[1]);
    if (!project) {
      app.append(element('h1', 'Project not found'));
    } else {
      app.append(element('h1', project.name));
      const form = element('form', undefined, 'create-form');
      const label = element('label', 'Task title'); label.htmlFor = 'task-title';
      const input = element('input'); input.id = 'task-title'; input.type = 'text'; input.setAttribute('aria-label', 'Task title');
      const submit = element('button', 'Create task'); submit.type = 'submit';
      const alert = element('p', '', 'alert'); alert.setAttribute('role', 'alert'); alert.hidden = true;
      form.append(label, input, submit, alert);
      form.addEventListener('submit', async event => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; input.focus(); return; }
        const response = await fetch(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
        if (response.ok) render();
      });
      app.append(form);
      const filterLabel = element('label', 'Task filter'); filterLabel.htmlFor = 'task-filter';
      const filter = element('select'); filter.id = 'task-filter'; filter.setAttribute('aria-label', 'Task filter');
      for (const value of ['All', 'Open', 'Completed']) { const option = element('option', value); option.value = value; filter.append(option); }
      app.append(filter);
      const taskList = element('section', undefined, 'task-list');
      const taskResponse = await fetch(`/api/projects/${match[1]}/tasks`);
      const tasks = taskResponse.ok ? await taskResponse.json() : [];
      const showTasks = () => {
        taskList.replaceChildren();
        for (const task of tasks) {
          if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
          const row = element('div', undefined, 'task-row'); row.dataset.testid = 'task-row';
          row.append(element('span', task.title));
          const checkbox = element('input'); checkbox.type = 'checkbox'; checkbox.checked = Boolean(task.completed); checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => { await fetch(`/api/projects/${match[1]}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) }); render(); });
          row.append(checkbox); taskList.append(row);
        }
      };
      filter.addEventListener('change', showTasks); showTasks(); app.append(taskList);
    }
    const back = element('button', 'Projects');
    back.type = 'button';
    back.addEventListener('click', () => navigate('/'));
    app.append(back);
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form', undefined, 'create-form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  input.setAttribute('aria-label', 'Project name');
  const submit = element('button', 'Create project');
  submit.type = 'submit';
  const alert = element('p', '', 'alert');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  form.append(label, input, submit, alert);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
    });
    if (response.ok) {
      input.value = '';
      alert.hidden = true;
      await render();
    }
  });
  app.append(form);

  let items;
  try { items = await projects(); } catch { app.append(element('p', 'Unable to load projects')); return; }
  const list = element('section', undefined, 'project-list');
  list.setAttribute('aria-label', 'Projects');
  for (const project of items) {
    const row = element('div', undefined, 'project-row');
    row.dataset.testid = 'project-row';
    row.append(element('span', project.name));
    const open = element('button', 'Open project');
    open.type = 'button';
    open.addEventListener('click', () => navigate(`/projects/${project.id}`));
    row.append(open);
    list.append(row);
  }
  app.append(list);
}

addEventListener('popstate', render);
render();

* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fb; color: #172033; font: 16px/1.5 system-ui, sans-serif; }
.container { width: min(720px, calc(100% - 32px)); margin: 56px auto; padding: 32px; background: #fff; border: 1px solid #e1e6ef; border-radius: 12px; box-shadow: 0 8px 24px #1720330d; }
h1 { margin: 0 0 24px; font-size: 2rem; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; align-items: center; }
.create-form label { grid-column: 1 / -1; font-weight: 600; }
input { min-width: 0; padding: 10px 12px; border: 1px solid #aab4c4; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #2458c6; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #1947a8; }
button:focus-visible, input:focus-visible { outline: 3px solid #8ab4ff; outline-offset: 2px; }
.alert { grid-column: 1 / -1; margin: 0; color: #b42318; }
.project-list { display: grid; gap: 10px; margin-top: 24px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border: 1px solid #e1e6ef; border-radius: 8px; }
.project-row span { overflow-wrap: anywhere; }
@media (max-width: 480px) { .container { margin: 20px auto; padding: 22px; } .create-form { grid-template-columns: 1fr; } .create-form label, .alert { grid-column: 1; } }

